'use client';
import { useState,useEffect,useCallback,createContext,useContext,useRef,useId,cloneElement,isValidElement,type ReactElement,type ReactNode,type FormEvent } from 'react';
import Link from 'next/link';
import { usePathname,useRouter } from 'next/navigation';
import { LayoutDashboard,ClipboardList,FileUp,MessageSquareText,ChartNoAxesGantt,Users,Library,Download,Settings,LogOut,ArrowUpRight,ArrowRight,Plus,Check,Clock,LockKeyhole,ChevronRight,Menu,X,FileText,CalendarDays,ShieldCheck,Search,RefreshCw,CheckCircle2,AlertCircle,BookOpen,UserRound,GraduationCap,ExternalLink,FolderOpen } from 'lucide-react';
import { STATUS,RUBRIC,COMMON,COURSE_RULE } from '@/lib/catalog';
type Item=Record<string,any>;
type Data={user:Item;modules:Item[];submissions:Item[];resources:Item[];users:Item[];milestones:Item[];settings:Item;contributions:Item[];peerReviews:Item[];audit:Item[];assignments:Item[];serverTime:string};
type Action=(path:string,payload?:unknown,method?:string)=>Promise<boolean>;
const Context=createContext<{data:Data;act:Action;busy:boolean;download:(kind:string)=>Promise<void>;reload:()=>Promise<void>}|null>(null);
const useApp=()=>useContext(Context)!;
const fmt=(s:string,short=false)=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',...(!short?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(s));
const localDate=(s:string)=>{const d=new Date(new Date(s).getTime()+8*3600000);return d.toISOString().slice(0,16);};
const fromLocal=(s:string)=>new Date(s+':00+08:00').toISOString();
const completed=(m:Item)=>['APPROVED','FROZEN'].includes(m.status);
const overdue=(m:Item)=>!completed(m)&&new Date(m.due_at).getTime()<Date.now();
function Badge({status}:{status:string}){return <span className={`badge ${status.toLowerCase()}`}><i/>{STATUS[status]||status}</span>;}
function Avatar({name,admin=false}:{name:string;admin?:boolean}){return <span className={`avatar ${admin?'admin-avatar':''}`}>{name?.slice(-2)}</span>;}
function Empty({title='暂无记录',detail='完成操作后，相关内容会显示在这里。'}:{title?:string;detail?:string}){return <div className="empty"><FolderOpen size={30}/><strong>{title}</strong><p>{detail}</p></div>;}
function Heading({eyebrow,title,detail,children}:{eyebrow:string;title:string;detail:string;children?:ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{detail}</p></div><div className="heading-actions">{children}</div></div>;}
function Modal({title,children,close}:{title:string;children:ReactNode;close:()=>void}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{ref.current?.showModal();return()=>ref.current?.close();},[]);return <dialog ref={ref} onCancel={close} onClick={e=>{if(e.target===e.currentTarget)close();}} aria-label={title}><div className="modal-head"><h2>{title}</h2><button className="icon-button" onClick={close} aria-label="关闭"><X size={20}/></button></div><div className="modal-body">{children}</div></dialog>;}
function Field({label,children,hint}:{label:string;children:ReactNode;hint?:string}){const id=useId();const control=isValidElement(children)?cloneElement(children as ReactElement<{id:string;"aria-describedby"?:string}>,{id,"aria-describedby":hint?id+"-hint":undefined}):children;return <div className="field"><label className="field-label" htmlFor={id}><span>{label}</span></label>{control}{hint&&<small id={id+"-hint"}>{hint}</small>}</div>;}
function Submit({children='保存'}:{children?:ReactNode}){const {busy}=useApp();return <button className="button primary" type="submit" disabled={busy}>{busy?<RefreshCw size={16} className="spin"/>:<Check size={16}/>} {children}</button>;}
function FileLinks({files}:{files:Item[]}){return <div className="file-list">{files.map(f=><a className="file-link" href={'/api/files/'+f.id} key={f.id}><FileText size={18}/><span>{f.original_name}<small>{(f.size/1024/1024).toFixed(2)} MB · 下载原文件</small></span><Download size={16}/></a>)}</div>;}
function FileInput({required=false}:{required?:boolean}){return <Field label="附件" hint="可多选，最多5个；每个20MB以内。DOCX / XLSX / PDF / PPTX / PNG / JPG / TXT / CSV / MD。"><input type="file" name="files" multiple required={required} accept=".docx,.xlsx,.pdf,.pptx,.png,.jpg,.jpeg,.txt,.csv,.md"/></Field>;}

export default function Workspace(){
 const path=usePathname(),router=useRouter();const [data,setData]=useState<Data|null>(null),[user,setUser]=useState<Item|null>(null),[busy,setBusy]=useState(false),[notice,setNotice]=useState<{text:string;error?:boolean}|null>(null),[menu,setMenu]=useState(false);
 const reload=useCallback(async()=>{try{const r=await fetch('/api/state',{cache:'no-store'});const j=await r.json();if(r.status===401){setData(null);router.replace('/login');return;}if(r.status===428){const me=await fetch('/api/me').then(r=>r.json());setUser({...me.user,forcePasswordChange:me.forcePasswordChange});router.replace('/account');return;}if(!r.ok)throw new Error(j.error);setData(j);setUser(j.user);}catch(e){setNotice({text:(e as Error).message,error:true});}},[router]);
 useEffect(()=>{if(path!=='/login'){void reload();const timer=setInterval(()=>void reload(),15000);return()=>clearInterval(timer);}},[path,reload]);
 useEffect(()=>{setMenu(false);},[path]);
 const act:Action=async(url,payload,method='POST')=>{setBusy(true);setNotice(null);try{const multipart=payload instanceof FormData;const r=await fetch('/api/'+url,{method,headers:multipart?{}:{'Content-Type':'application/json'},body:multipart?payload:JSON.stringify(payload||{})});const j=await r.json();if(!r.ok)throw new Error(j.error||'操作失败');await reload();setNotice({text:'已保存，项目数据已更新。'});return true;}catch(e){setNotice({text:(e as Error).message,error:true});return false;}finally{setBusy(false);}};
 async function download(kind:string){setBusy(true);try{const r=await fetch('/api/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind})});if(!r.ok)throw new Error((await r.json()).error);const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=kind==='final'?'MedPolicyLab_Final.zip':'MedPolicyLab_Working.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);await reload();setNotice({text:'资料包已生成并开始下载。'});}catch(e){setNotice({text:(e as Error).message,error:true});}finally{setBusy(false);}}
 if(path==='/login')return <Login onLogin={()=>void reload()}/>;
 if(!data&&path==='/account'&&user)return <div className="password-gate"><Brand/><div className="panel"><h1>请先修改初始密码</h1><p>组长已开启首次登录密码保护。</p><PasswordForm standalone onDone={reload}/></div></div>;
 if(!data)return <div className="loading"><Brand/><RefreshCw className="spin"/><p>正在连接研究工作台…</p>{notice&&<p role="alert">{notice.text}</p>}<Link href="/login">返回登录</Link></div>;
 const admin=data.user.role==='ADMIN';
 const nav=[['/dashboard','项目概览',LayoutDashboard],['/my-task','我的研究模块',ClipboardList],['/tasks','研究任务',BookOpen],['/submissions','提交与版本',FileUp],['/reviews',admin?'审核中心':'审核反馈',MessageSquareText],['/timeline','项目甘特图',ChartNoAxesGantt],['/members','成员与贡献',Users],['/peer-review','组内互评',GraduationCap],['/resources','课程资料库',Library],...(admin?[['/export','资料打包导出',Download],['/admin','组长管理',Settings]]:[])] as [string,string,typeof LayoutDashboard][];
 const page=path==='/'?'dashboard':path.split('/')[1];
 const adminOnly=['admin','export'].includes(page)&&!admin;
 return <Context.Provider value={{data,act,busy,download,reload}}><div className="app-shell">
  {menu&&<div className="mobile-shade" onClick={()=>setMenu(false)}/>}
  <aside className={menu?'sidebar visible':'sidebar'}><Link href="/dashboard" className="brand-link"><Brand/></Link><div className="workspace-label"><span className="group-icon">07</span><div>卫生经济学 · 第7组<small>温州医科大学</small></div><ChevronRight size={15}/></div><div className="nav-caption">研究协作空间</div><nav>{nav.filter(([href])=>!admin||href!=='/my-task').map(([href,label,Icon])=><Link key={href} href={href} className={(path===href||(path==='/'&&href==='/dashboard')||(path.startsWith('/tasks/')&&href==='/tasks'))?'active':''}><Icon size={18}/><span>{label}</span>{href==='/reviews'&&data.modules.filter(m=>['SUBMITTED','IN_REVIEW'].includes(m.status)).length>0&&<em>{data.modules.filter(m=>['SUBMITTED','IN_REVIEW'].includes(m.status)).length}</em>}</Link>)}</nav><div className="sidebar-bottom"><div className="sidebar-note"><span className="live-dot"/> 项目资料持久化保存<small>共同研究，清晰协作。</small></div><Link className="profile" href="/account"><Avatar name={data.user.name} admin={admin}/><span>{data.user.name}<small>{admin?'组长 · 项目管理员':'研究成员'} · 账号设置</small></span><Settings size={16}/></Link></div></aside>
  <div className="main-area"><header className="topbar"><div className="topbar-left"><button className="icon-button mobile-menu" onClick={()=>setMenu(!menu)} aria-label="打开导航"><Menu size={22}/></button><span className="breadcrumb">工作空间 <ChevronRight size={13}/> {nav.find(([href])=>href==='/'+page)?.[1]||'研究模块'}</span></div><div className="topbar-right"><span className="timezone"><span className="live-dot"/> 北京时间</span><button className="icon-button" onClick={()=>void reload()} aria-label="刷新数据"><RefreshCw size={17}/></button><button className="icon-button" aria-label="退出登录" onClick={async()=>{await fetch('/api/logout',{method:'POST'});setData(null);router.push('/login');}}><LogOut size={17}/></button></div></header>
  <main>{notice&&<div role={notice.error?'alert':'status'} className={`notice ${notice.error?'error':'success'}`}><span>{notice.text}</span><button onClick={()=>setNotice(null)} aria-label="关闭提示"><X size={16}/></button></div>}{data.user.must_change===1&&<div className="notice warning"><span>你仍在使用初始或重置密码，请尽早修改，保护研究材料。</span><Link href="/account">修改密码 <ArrowRight size={14}/></Link></div>}
   {adminOnly?<Empty title="此页面仅组长可访问" detail="你的研究模块、提交材料和审核反馈仍可正常使用。"/>:page==='dashboard'?<Dashboard/>:page==='tasks'?(path.split('/')[2]?<TaskDetail id={path.split('/')[2]}/>:<Tasks/>):page==='my-task'?(data.modules.find(m=>m.owner_id===data.user.id)?<TaskDetail id={data.modules.find(m=>m.owner_id===data.user.id)!.id}/>:<Empty title="组长专注项目统筹" detail="组长不分配研究专题，请在研究任务和审核中心管理11个模块。"/>):page==='submissions'?<Submissions/>:page==='reviews'?<Reviews/>:page==='timeline'?<Timeline/>:page==='resources'?<Resources/>:page==='members'?<Members/>:page==='peer-review'?<PeerReview/>:page==='export'?<ExportPage/>:page==='admin'?<Admin/>:page==='account'?<Account/>:<Empty title="页面不存在"/>}
  <footer>MedPolicy Lab <span>温州医科大学 · 卫生经济学第7组</span><span>内部协作平台 · 2026</span></footer></main></div></div></Context.Provider>;
}
function Brand(){return <div className="brand"><span className="brand-mark"><i/><i/><i/><i/></span><span>MedPolicy <b>Lab</b><small>卫生经济学研究协作平台</small></span></div>;}
function Login({onLogin}:{onLogin:()=>void}){
 const router=useRouter();const [busy,setBusy]=useState(false),[error,setError]=useState('');
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);setError('');try{const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({studentId:f.get('studentId'),password:f.get('password')})});const j=await r.json();if(!r.ok)throw new Error(j.error);onLogin();router.push(j.user.must_change&&j.forcePasswordChange?'/account':j.user.role==='ADMIN'?'/dashboard':'/my-task');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 return <div className="login-page"><section className="login-story"><Brand/><div className="login-story-content"><div className="eyebrow">WENZHOU MEDICAL UNIVERSITY · GROUP 07</div><h1>让每一份研究，<br/>成为共同的成果。</h1><p>药品与医用耗材监管<br/>从审评审批到集中带量采购</p><div className="research-path"><span>教材内容</span><ArrowRight size={18}/><span>现实议题</span><ArrowRight size={18}/><span>必答思考</span></div><div className="login-metrics"><div><strong>11</strong><span>独立研究模块</span></div><div><strong>12</strong><span>协作成员</span></div><div><strong>15<small> min</small></strong><span>课堂汇报</span></div></div></div><div className="login-bottom"><CalendarDays size={17}/> 2026年11月3日 · 星期二下午</div></section><section className="login-form-wrap"><div className="login-form"><span className="section-tag"><ShieldCheck size={14}/> 第7组协作空间</span><h2>欢迎回到研究工作台</h2><p>使用完整学号登录，继续你的研究。</p><form onSubmit={submit}><Field label="学号"><input name="studentId" type="text" inputMode="numeric" autoComplete="username" pattern="[0-9]{10}" maxLength={10} placeholder="请输入10位完整学号" required/></Field><Field label="密码"><input name="password" type="password" autoComplete="current-password" placeholder="请输入登录密码" required/></Field>{error&&<div className="notice error" role="alert">{error}</div>}<button className="button primary login-submit" disabled={busy}>{busy?'正在登录…':'登录工作台'}<ArrowRight size={18}/></button></form><div className="login-help"><LockKeyhole size={16}/><p>首次登录后请尽早修改初始密码。<br/>忘记密码请联系组长重置。</p></div></div><div className="login-foot">研究 · 协作 · 证据</div></section></div>;
}

function Dashboard(){
 const {data}=useApp(),admin=data.user.role==='ADMIN',mods=data.modules;
 const count=(s:string[])=>mods.filter(m=>s.includes(m.status)).length;
 const done=count(['APPROVED','FROZEN']),percent=Math.round(done/Math.max(mods.length,1)*100),next=data.milestones.find(m=>new Date(m.at).getTime()>Date.now()),presentation=data.milestones.find(m=>m.id==='M8');
 const days=presentation?Math.max(0,Math.ceil((new Date(presentation.at).getTime()-Date.now())/86400000)):0;
 return <><Heading eyebrow="PROJECT OVERVIEW" title={`${data.user.name}，研究从这里推进`} detail="每一份材料都有负责人，每一次修改都有记录。"><Link className="button secondary" href="/timeline"><CalendarDays size={16}/> 查看项目计划</Link>{admin?<Link className="button primary" href="/reviews"><MessageSquareText size={16}/> 进入审核中心</Link>:<Link className="button primary" href="/my-task"><ArrowUpRight size={16}/> 我的研究模块</Link>}</Heading>
 <section className="project-hero"><div className="hero-copy"><div className="hero-meta"><span>卫生经济学课程研究</span><span className="hero-divider"/> 第7组</div><h2>药品与医用耗材监管</h2><p>从审评审批到集中带量采购</p><div className="hero-tags"><span><BookOpen size={14}/> 教材内容</span><ArrowRight size={13}/><span>现实议题</span><ArrowRight size={13}/><span>必答思考</span></div></div><div className="hero-deadline"><span>距离正式汇报</span><strong>{days}<small>天</small></strong><span>{presentation?fmt(presentation.at):'待设置'} · 约15分钟</span><small>下午具体时间待确认</small></div></section>
 <div className="stat-grid"><div className="stat-card"><div className="stat-label">{data.settings.public_progress||admin?'整体完成率':'我的模块完成率'} <CheckCircle2 size={17}/></div><strong>{percent}<small>%</small></strong><div className="progress-track"><span style={{width:percent+'%'}}/></div><small>{done} / {mods.length} 个模块已通过或冻结</small></div>{[['已提交模块',count(['SUBMITTED','IN_REVIEW','REVISION','APPROVED','FROZEN']),'已有研究版本','blue'],['待审核',count(['SUBMITTED','IN_REVIEW']),'等待组长处理','teal'],['需修改',count(['REVISION']),'等待补充与完善','amber'],['已冻结',count(['FROZEN']),'最终内容已锁定','navy'],['逾期模块',mods.filter(overdue).length,'按当前期限判断','red']].map(([label,n,sub,c])=><div className={`stat-card ${c}`} key={label}><div className="stat-label">{label}<span className="stat-dot"/></div><strong>{n}</strong><small>{sub}</small></div>)}</div>
 <div className="dashboard-grid"><section className="panel"><div className="panel-heading"><div><h2>研究模块进展 <span className="count">{mods.length}</span></h2><p>以审核通过为完成依据，不按上传数量累计。</p></div><Link href="/tasks" className="text-link">全部任务 <ArrowRight size={14}/></Link></div><TaskTable modules={mods} compact/></section><div className="right-stack"><section className="panel next-milestone"><div className="panel-kicker"><span className="live-dot"/> 下一项里程碑</div><h3>{next?.title||'计划节点已结束'}</h3><div className="milestone-time"><CalendarDays size={17}/>{next?fmt(next.at):'请关注最终成果'}</div><p>{next?.description||'组长可在甘特图中调整时间安排。'}</p><Link href="/timeline" className="text-link">查看完整时间安排 <ArrowRight size={14}/></Link></section><section className="panel questions-card"><div className="panel-kicker">RESEARCH QUESTIONS</div><h3>让研究回应真实问题</h3><div className="research-question"><span>01</span><p>价格大幅下降后，如何保障<strong>质量与供应稳定</strong>？</p></div><div className="research-question"><span>02</span><p>监管如何平衡<strong>患者可及性</strong>与<strong>企业创新激励</strong>？</p></div></section><section className="panel workflow-card"><h3>我们的审核流程</h3><p>成员提交 → 组长下载 → ChatGPT审阅 → 录入反馈 → 修改与终审</p><span className="subtle">评分由组长人工录入，以帮助研究改进。</span></section></div></div>
 <div className="course-rule"><GraduationCap size={20}/><p>{COURSE_RULE}</p></div></>;
}
function TaskTable({modules,compact=false}:{modules:Item[];compact?:boolean}){return <div className="table-wrap"><table><thead><tr><th>研究模块</th><th>负责人</th><th>状态</th>{!compact&&<th>进度</th>}<th>截止时间</th></tr></thead><tbody>{modules.map(m=><tr key={m.id}><td><Link href={'/tasks/'+m.id} className="task-title"><span className="module-id">{m.id}</span><span>{m.title}{!compact&&<small>{m.category} · {m.priority}优先级 · 预计 {m.estimated_hours} 小时</small>}</span></Link></td><td><span className="person"><Avatar name={m.owner_name}/>{m.owner_name}</span></td><td><Badge status={m.status}/></td>{!compact&&<td><div className="inline-progress"><div className="progress-track"><span style={{width:m.progress+'%'}}/></div>{m.progress}%</div></td>}<td className={overdue(m)?'overdue':'muted'}>{fmt(m.due_at)}{overdue(m)&&<small>已逾期</small>}</td></tr>)}</tbody></table>{modules.length===0&&<Empty title="没有符合筛选条件的任务"/>}</div>;}
function Filters({owner,setOwner,status,setStatus,search,setSearch}:{owner:string;setOwner:(s:string)=>void;status:string;setStatus:(s:string)=>void;search:string;setSearch:(s:string)=>void}){const {data}=useApp();return <div className="filters"><div className="search"><Search size={17}/><input aria-label="搜索研究模块" placeholder="搜索模块编号或主题…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="按负责人筛选" value={owner} onChange={e=>setOwner(e.target.value)}><option value="">全部负责人</option>{data.users.filter(u=>u.role==='MEMBER').map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select><select aria-label="按任务状态筛选" value={status} onChange={e=>setStatus(e.target.value)}><option value="">全部状态</option>{Object.entries(STATUS).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></div>;}
function useFilters(){const [owner,setOwner]=useState(''),[status,setStatus]=useState(''),[search,setSearch]=useState('');const {data}=useApp();return {props:{owner,setOwner,status,setStatus,search,setSearch},modules:data.modules.filter(m=>(!owner||m.owner_id===owner)&&(!status||m.status===status)&&(!search||(m.id+m.title).toLowerCase().includes(search.toLowerCase())))};}
function Tasks(){const f=useFilters();return <><Heading eyebrow="RESEARCH MODULES" title="11个专题，一个共同目标" detail="每人一个独立研究模块，从制度基础到政策综合回应。"/><section className="panel"><Filters {...f.props}/><TaskTable modules={f.modules}/></section><p className="footnote">点击模块查看任务、提交材料与历史反馈。负责人及日期由组长统一调整。</p></>;}

function TaskDetail({id}:{id:string}){
 const {data,act}=useApp(),m=data.modules.find(m=>m.id===id);const [tab,setTab]=useState('brief'),[editing,setEditing]=useState(false),[assign,setAssign]=useState(false),[adding,setAdding]=useState(false);
 if(!m)return <Empty title="模块不存在或未获授权"/>;
 const admin=data.user.role==='ADMIN',own=m.owner_id===data.user.id,subs=data.submissions.filter(s=>s.module_id===id).sort((a,b)=>b.version-a.version),resources=data.resources.filter(r=>!r.modules.length||r.modules.includes(id)),editable=!completed(m);
 return <><Link className="back-link" href="/tasks">研究任务 <ChevronRight size={13}/> {id}</Link><Heading eyebrow={`${id} · ${m.category}`} title={m.title} detail={m.purpose}>{admin&&<><button className="button secondary" onClick={()=>setAssign(true)}><Users size={16}/> 调整负责人</button><button className="button primary" onClick={()=>setEditing(true)}><Settings size={16}/> 编辑任务</button></>}</Heading><div className="task-meta"><span className="person"><Avatar name={m.owner_name}/>{m.owner_name}</span><Badge status={m.status}/><span><CalendarDays size={16}/> 截止 {fmt(m.due_at)}</span><span><Clock size={16}/> 预计 {m.estimated_hours} 小时</span><span className={overdue(m)?'overdue':''}>{overdue(m)?'已逾期，请尽快与组长沟通':m.priority+'优先级'}</span></div>
 <div className="tabs">{[['brief','任务说明'],['submit','提交材料'],['feedback','审核与版本']].map(([k,v])=><button className={tab===k?'active':''} onClick={()=>setTab(k)} key={k}>{v}{k==='feedback'&&<span>{subs.length}</span>}</button>)}</div>
 {tab==='brief'&&<div className="detail-grid"><div className="left-stack"><section className="panel padded"><div className="section-heading"><BookOpen size={19}/><h2>具体研究问题</h2></div><ol className="numbered-list">{m.questions.map((q:string,i:number)=><li key={i}><span>{String(i+1).padStart(2,'0')}</span>{q}</li>)}</ol></section><section className="panel padded"><h2>需要交付什么</h2><ul className="check-list">{m.deliverables.map((q:string,i:number)=><li key={i}><CheckCircle2 size={16}/>{q}</li>)}</ul><div className="soft-note">{COMMON}</div></section>{m.hints&&<section className="panel padded"><h2>课程理论提示</h2><p className="prewrap">{m.hints}</p><small className="muted">课件定位与应用建议，政策事实仍需单独核验。</small></section>}{m.public_summary&&<section className="panel padded"><h2>组长公开的成果摘要</h2><p className="prewrap">{m.public_summary}</p></section>}</div><div className="right-stack"><section className="panel padded"><h3>当前工作进度</h3><div className="big-progress">{m.progress}<small>%</small></div><div className="progress-track"><span style={{width:m.progress+'%'}}/></div>{(own||admin)&&editable&&<form className="small-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await act('modules/'+id,{progress:Number(f.get('progress')),actual_hours:Number(f.get('actual_hours'))},'PATCH');}}><Field label="工作进度（审核通过后为100%）"><input type="number" name="progress" min="0" max="90" defaultValue={Math.min(m.progress,90)} required/></Field><Field label="累计实际工作量（小时）"><input type="number" name="actual_hours" min="0" max="1000" step="0.5" defaultValue={m.actual_hours}/></Field><Submit>更新进度</Submit></form>}<p className="footnote">实际提交：{m.submitted_at?fmt(m.submitted_at):'尚未提交'}</p></section><section className="panel padded"><div className="section-heading"><h3>子任务清单</h3>{admin&&m.status!=='FROZEN'&&<button className="icon-button" onClick={()=>setAdding(true)} aria-label="新增子任务"><Plus size={18}/></button>}</div>{m.subtasks.length?m.subtasks.map((s:Item)=><div className="subtask" key={s.id}><label><input type="checkbox" checked={!!s.done} disabled={(!own&&!admin)||m.status==='FROZEN'} onChange={e=>void act('subtasks/'+s.id,{done:e.target.checked},'PATCH')}/><span>{s.title}</span></label>{admin&&<button className="icon-button" aria-label={'删除'+s.title} onClick={()=>{if(confirm('删除此子任务？操作会保留日志。'))void act('subtasks/'+s.id,{},'DELETE');}}><X size={14}/></button>}</div>):<p className="muted">暂无子任务，由组长按需要添加。</p>}</section><section className="panel padded"><h3>相关课程资料 <span className="count">{resources.length}</span></h3>{resources.map(r=><div key={r.id} className="mini-resource"><FileText size={17}/><div><strong>{r.title}</strong><FileLinks files={r.files}/></div></div>)}{!resources.length&&<p className="muted">组长可在资料库上传并关联课件。</p>}</section></div></div>}
 {tab==='submit'&&(own?(editable?<SubmissionForm module={m} previous={subs[0]}/>:<div className="panel padded"><LockKeyhole size={26}/><h2>此模块已通过或冻结</h2><p>如需继续调整，请由组长重新开放。现有版本和审核记录会完整保留。</p></div>):<Empty title={admin?'由研究负责人提交材料':'你不是当前负责人'} detail="组长可在审核中心处理材料；普通成员只能编辑当前负责的研究模块。"/>)}
 {tab==='feedback'&&<div className="version-list"><ScoreHistory submissions={subs}/>{subs.length?subs.map(s=><SubmissionCard s={s} key={s.id} admin={admin}/>):<Empty title="还没有提交版本" detail="提交后将依次保存为 V1、V2、V3，审核意见与对应版本关联。"/>}</div>}
 {editing&&<Modal title={`编辑 ${id} 任务`} close={()=>setEditing(false)}><EditTask m={m} close={()=>setEditing(false)}/></Modal>}
 {assign&&<Modal title="调整研究负责人" close={()=>setAssign(false)}><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(await act('assignments/swap',{moduleId:id,memberId:f.get('memberId')}))setAssign(false);}}><div className="soft-note">选择已有模块的成员会交换两人的任务。原文件、提交人、贡献及历史评分保持原归属。</div><Field label="新负责人"><select name="memberId" required defaultValue=""><option value="" disabled>选择研究成员</option>{data.users.filter(u=>u.role==='MEMBER'&&u.id!==m.owner_id&&!u.disabled).map(u=><option key={u.id} value={u.id}>{u.name} · {data.modules.find(m=>m.owner_id===u.id)?.id||'未分配'}</option>)}</select></Field><Submit>确认交换负责人</Submit></form></Modal>}
 {adding&&<Modal title="新增子任务" close={()=>setAdding(false)}><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(await act('subtasks',{moduleId:id,title:f.get('title')}))setAdding(false);}}><Field label="子任务内容"><input name="title" required minLength={2}/></Field><Submit>添加子任务</Submit></form></Modal>}
 </>;
}
function ScoreHistory({submissions}:{submissions:Item[]}){const scored=[...submissions].filter(s=>s.reviews.length).sort((a,b)=>a.version-b.version);if(!scored.length)return null;return <section className="panel"><div className="panel-heading"><div><h2>版本评分变化</h2><p>每个版本展示最近一次人工评价；评分始终归属原提交人。</p></div></div><div className="table-wrap"><table><thead><tr><th>版本</th><th>原提交人</th><th>内部评分 / 100</th><th>较上一评分版本</th><th>最近审核</th></tr></thead><tbody>{scored.map((s,i)=>{const r=s.reviews.at(-1),previous=scored[i-1]?.reviews.at(-1),delta=previous?r.total-previous.total:null;return <tr key={s.id}><td>V{s.version}</td><td>{s.submitter_name}</td><td><strong>{r.total}</strong></td><td className={delta!==null&&delta>0?'text-teal':'muted'}>{delta===null?'—':(delta>0?'+':'')+delta}</td><td><Badge status={r.conclusion}/> <span className="muted">{fmt(r.created_at)}</span></td></tr>;})}</tbody></table></div></section>;}
function EditTask({m,close}:{m:Item;close:()=>void}){const {act}=useApp();return <form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(await act('modules/'+m.id,{title:f.get('title'),purpose:f.get('purpose'),questions:String(f.get('questions')).split('\n').filter(Boolean),deliverables:String(f.get('deliverables')).split('\n').filter(Boolean),hints:f.get('hints'),start_at:fromLocal(String(f.get('start_at'))),due_at:fromLocal(String(f.get('due_at'))),priority:f.get('priority'),estimated_hours:Number(f.get('estimated_hours')),public_summary:f.get('public_summary')},'PATCH'))close();}}><Field label="任务名称"><input name="title" defaultValue={m.title} required/></Field><Field label="研究目的"><textarea name="purpose" defaultValue={m.purpose} required rows={2}/></Field><Field label="研究问题（每行一项）"><textarea name="questions" defaultValue={m.questions.join('\n')} rows={5} required/></Field><Field label="交付要求（每行一项）"><textarea name="deliverables" defaultValue={m.deliverables.join('\n')} rows={4} required/></Field><div className="form-grid"><Field label="开始时间（北京时间）"><input name="start_at" type="datetime-local" defaultValue={localDate(m.start_at)} required/></Field><Field label="截止时间（北京时间）"><input name="due_at" type="datetime-local" defaultValue={localDate(m.due_at)} required/></Field><Field label="优先级"><select name="priority" defaultValue={m.priority}>{['普通','重要','紧急'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="预计工作量（小时）"><input type="number" name="estimated_hours" min="0" max="200" step="0.5" defaultValue={m.estimated_hours}/></Field></div><Field label="理论提示"><textarea name="hints" defaultValue={m.hints} rows={3}/></Field><Field label="授权公开的成果摘要"><textarea name="public_summary" defaultValue={m.public_summary} rows={3}/></Field><Submit>保存任务设置</Submit></form>;}
function SubmissionForm({module:m,previous}:{module:Item;previous?:Item}){const {act}=useApp(),[files,setFiles]=useState(0);return <section className="panel padded submission-form"><div className="section-heading"><h2>提交 {previous?'V'+(previous.version+1):'V1'} 研究材料</h2><span className="section-tag">原始文件与历史版本永久保留</span></div><p className="muted">{COMMON}</p><form onSubmit={async e=>{e.preventDefault();const formEl=e.currentTarget,f=new FormData(formEl);f.set('moduleId',m.id);const sources=[1,2,3].map(i=>({title:String(f.get('source_title_'+i)||''),url:String(f.get('source_url_'+i)||'')})).filter(s=>s.title||s.url);f.set('sources',JSON.stringify(sources));f.set('requirements_met',String(f.get('requirements_met')==='on'));f.set('feedback_addressed',String(f.get('feedback_addressed')==='on'));if(await act('submissions',f)){formEl.reset();setFiles(0);}}}><Field label="研究摘要" hint="简要概括主要结论与可用于汇报的素材，至少10字。"><textarea name="summary" minLength={10} maxLength={3000} rows={3} required placeholder="本模块回答了什么问题，核心发现是什么…" defaultValue={previous?.summary||''}/></Field><Field label="在线研究正文（与Word/PDF文档二选一）" hint="建议约1000字。在线提交至少600字；上传Word/PDF时可不填写。"><textarea name="content" rows={12} maxLength={50000} placeholder="按教材理论、现实证据、经济学分析与结论组织…" defaultValue={previous?.content||''}/></Field><div onChange={e=>{const t=e.target as HTMLInputElement;if(t.files)setFiles(t.files.length);}}><FileInput/></div>{files>0&&<small className="muted">已选择 {files} 个附件。本次需重新选择要包含在新版本中的全部附件。</small>}<h3>参考来源（2—3条）</h3><p className="footnote">填写真实标题与官方链接，或完整书目、页码。系统不自动验证来源真实性，组长会在审核时核对。</p>{[1,2,3].map(i=><div className="source-row" key={i}><span>{String(i).padStart(2,'0')}</span><Field label={`来源${i}标题${i===3?'（可选）':''}`}><input name={'source_title_'+i} required={i<3} defaultValue={previous?.sources?.[i-1]?.title||''} placeholder="政策文件或研究名称"/></Field><Field label="链接或书目定位"><input name={'source_url_'+i} required={i<3} defaultValue={previous?.sources?.[i-1]?.url||''} placeholder="https://… 或 教材名、版次与页码"/></Field></div>)}<Field label="本次修改说明"><textarea name="change_note" rows={3} minLength={2} required placeholder={previous?'回应了哪些审核问题，修改了什么…':'初次提交：内容范围与待核实事项…'}/></Field><Field label="本次投入时间（小时，避免重复累计）"><input name="actual_hours" type="number" min="0" max="200" step="0.5" defaultValue="0"/></Field><div className="checkbox-stack"><label><input type="checkbox" name="requirements_met"/> 我已逐项检查模块交付要求（自评）</label><label><input type="checkbox" name="feedback_addressed"/> 我已在本次修改中回应上轮审核意见（如有）</label></div><div className="form-footer"><span>提交后生成新版本，不覆盖原始材料。</span><Submit>提交研究材料</Submit></div></form></section>;}

function SubmissionCard({s,admin=false}:{s:Item;admin?:boolean}){const {act,busy,data}=useApp(),[review,setReview]=useState(false);const latest=!data.submissions.some(x=>x.module_id===s.module_id&&x.version>s.version),m=data.modules.find(m=>m.id===s.module_id);return <article className="panel submission-card"><div className="submission-head"><div><span className="version-pill">V{s.version}</span><Link href={'/tasks/'+s.module_id}><strong>{s.module_id} · {data.modules.find(m=>m.id===s.module_id)?.title}</strong></Link><p>{s.submitter_name}提交 · {fmt(s.created_at)} <span className={s.on_time?'text-teal':'text-amber'}>{s.on_time?'按时提交':'超出当时截止时间'}</span></p></div><Badge status={s.status}/></div><p className="prewrap">{s.summary}</p><FileLinks files={s.files}/>{s.content&&<details><summary>查看在线研究正文</summary><div className="research-content">{s.content}</div></details>}<details><summary>参考来源与修改说明</summary><p className="prewrap">{s.change_note}</p><ul>{s.sources.map((r:Item,i:number)=><li key={i}>{r.title}：{/^https?:\/\//.test(r.url)?<a href={r.url} target="_blank" rel="noopener noreferrer">{r.url}<ExternalLink size={12}/></a>:r.url}</li>)}</ul><p className="muted">本次投入 {s.actual_hours} 小时 · 要求自评：{s.requirements_met?'已检查':'未确认'} · 反馈回应自评：{s.feedback_addressed?'已回应':'未确认/无上轮意见'}</p></details>{s.reviews.map((r:Item)=><div className="review-record" key={r.id}><div className="review-title"><strong>组长审核 · {fmt(r.created_at)}</strong><span><b>{r.total}</b> / 100 <Badge status={r.conclusion}/></span></div><div className="score-grid">{RUBRIC.map(([label,max],i)=><div key={label}><span>{label}</span><strong>{r.scores[i]} <small>/ {max}</small></strong></div>)}</div>{r.total>=85&&<p className="text-teal footnote">内部量表建议终审；是否通过以组长审核结论为准。</p>}{r.issues&&<div><h4>主要问题</h4><p className="prewrap">{r.issues}</p></div>}<div><h4>修改意见与处理说明</h4><p className="prewrap">{r.feedback}</p></div>{r.chatgpt_text&&<details><summary>ChatGPT反馈原文（人工录入）</summary><p className="prewrap">{r.chatgpt_text}</p></details>}<FileLinks files={r.files}/></div>)}{admin&&latest&&<div className="actions-row">{['SUBMITTED','IN_REVIEW','REVISION'].includes(s.status)&&m?.status!=='FROZEN'&&<><button className="button primary" onClick={()=>setReview(true)}>录入评分与审核</button>{s.status==='SUBMITTED'&&<button className="button secondary" disabled={busy} onClick={()=>void act(`submissions/${s.id}/start`)}>标记审核中</button>}</>}{s.status==='APPROVED'&&m?.status==='APPROVED'&&<button className="button primary" disabled={busy} onClick={()=>void act(`submissions/${s.id}/freeze`)}><LockKeyhole size={15}/> 冻结此版本</button>}{['APPROVED','FROZEN'].includes(m?.status)&&<button className="button secondary" disabled={busy} onClick={()=>{if(confirm('重新开放后，负责人可以提交新版本；原批准版本会完整保留。'))void act(`submissions/${s.id}/reopen`);}}>重新开放修改</button>}</div>}{review&&<Modal title={`${s.module_id} · V${s.version} 人工审核`} close={()=>setReview(false)}><ReviewForm s={s} close={()=>setReview(false)}/></Modal>}</article>;}
function ReviewForm({s,close}:{s:Item;close:()=>void}){const {act}=useApp(),[scores,setScores]=useState<string[]>(Array(6).fill(''));const total=scores.every(s=>s!=='')?scores.reduce((n,v)=>n+Number(v),0):null;return <form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);f.set('submissionId',s.id);f.set('scores',JSON.stringify(scores.map(Number)));if(await act('reviews',f))close();}}><div className="soft-note">请先下载材料，在对应ChatGPT对话中审核，再按证据录入评价。本量表仅用于内部改进，不是正式课程成绩。</div><div className="form-grid">{RUBRIC.map(([label,max],i)=><Field label={`${label}（${max}分）`} key={label}><input type="number" min="0" max={max} step="0.5" required value={scores[i]} onChange={e=>setScores(a=>a.map((x,j)=>i===j?e.target.value:x))}/></Field>)}</div><div className="score-total">内部评分合计 <strong>{total??'—'}<small> / 100</small></strong>{total!==null&&total>=85&&<span className="badge approved">建议终审</span>}</div><Field label="主要问题"><textarea name="issues" rows={3} placeholder="事实错误、证据缺口、理论使用或表达问题…"/></Field><Field label="修改意见 / 审核依据"><textarea name="feedback" rows={5} minLength={2} required placeholder="逐项写明需要修改或已经解决的问题；严重事实错误或伪造资料可要求重做。"/></Field><Field label="粘贴ChatGPT反馈原文（可选）"><textarea name="chatgpt_text" rows={5}/></Field><FileInput/><Field label="审核结论"><select name="conclusion" required defaultValue=""><option value="" disabled>请选择审核结论</option><option value="REVISION">退回修改 / 要求重做</option><option value="APPROVED">审核通过</option></select></Field><Submit>保存评价与结论</Submit></form>;}
function Submissions(){const {data}=useApp(),[filter,setFilter]=useState('');const subs=data.submissions.filter(s=>!filter||s.module_id===filter);return <><Heading eyebrow="SUBMISSIONS & VERSIONS" title="提交与版本记录" detail="每次提交独立保存，原始作者、文件和修改说明始终可追溯。"/><div className="filters"><select aria-label="按模块筛选提交" value={filter} onChange={e=>setFilter(e.target.value)}><option value="">全部可访问模块</option>{data.modules.map(m=><option key={m.id} value={m.id}>{m.id} · {m.title}</option>)}</select><span className="muted">共 {subs.length} 个版本</span></div><div className="version-list">{subs.length?subs.map(s=><SubmissionCard key={s.id} s={s} admin={data.user.role==='ADMIN'}/>):<Empty title="尚未收到研究材料" detail="成员可进入自己的研究模块，填写正文或上传Word/PDF及补充附件。"/>}</div></>;}
function Reviews(){const {data}=useApp(),admin=data.user.role==='ADMIN',[filter,setFilter]=useState('pending');const latest=data.submissions.filter(s=>!data.submissions.some(x=>x.module_id===s.module_id&&x.version>s.version));const subs=admin?(filter==='pending'?latest.filter(s=>['SUBMITTED','IN_REVIEW','REVISION'].includes(s.status)):latest):data.submissions;return <><Heading eyebrow="MANUAL REVIEW" title={admin?'组长审核中心':'我的审核反馈'} detail="下载材料 → 在ChatGPT独立对话中审阅 → 人工录入评分与建议 → 修改与终审。"/>{admin&&<div className="tabs"><button className={filter==='pending'?'active':''} onClick={()=>setFilter('pending')}>待处理与需修改</button><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>全部最新版本</button></div>}<div className="version-list">{subs.length?subs.map(s=><SubmissionCard key={s.id} s={s} admin={admin}/>):<Empty title={admin?'当前没有待处理材料':'暂时没有审核反馈'} detail="提交后的评分和修改意见会关联到对应版本，刷新或稍候即可看到最新状态。"/>}</div></>;}
function Timeline(){
 const {data,act}=useApp(),f=useFilters(),admin=data.user.role==='ADMIN';const [edit,setEdit]=useState<Item|null>(null),[milestone,setMilestone]=useState<Item|null>(null);
 const allDates=[...data.modules.flatMap(m=>[m.start_at,m.due_at]),...data.milestones.map(m=>m.at)];
 const min=Math.min(...allDates.map(d=>new Date(d).getTime())),max=Math.max(...allDates.map(d=>new Date(d).getTime()));
 const start=new Date(localDate(new Date(min).toISOString()).slice(0,10)+'T00:00:00+08:00').getTime(),end=new Date(localDate(new Date(max).toISOString()).slice(0,10)+'T00:00:00+08:00').getTime()+86400000;
 const days=Math.max(1,Math.ceil((end-start)/86400000)),step=Math.max(1,Math.ceil(days/30)),columns=Math.ceil(days/step),width=Math.max(700,columns*92),today=(Date.now()-start)/(end-start)*100;
 return <><Heading eyebrow="PROJECT TIMELINE" title="把研究进度放在同一张图上" detail="北京时间 · 点击任务查看详情，组长可编辑日期与分工，成员在模块页更新进度。"/><section className="panel"><Filters {...f.props}/><div className="gantt-legend">{['IN_PROGRESS','SUBMITTED','REVISION','APPROVED','FROZEN'].map(s=><Badge status={s} key={s}/>)}<span className="muted">条形长度 = 计划时间 · 深色填充 = 已记录进度</span></div><div className="gantt-scroll"><div className="gantt" style={{minWidth:width+290}}><div className="gantt-header"><div>研究模块 / 负责人</div><div className="gantt-dates" style={{gridTemplateColumns:`repeat(${columns},1fr)`}}>{Array.from({length:columns},(_,i)=><span key={i}>{fmt(new Date(start+i*step*86400000).toISOString(),true)}</span>)}</div></div>{f.modules.map(m=>{const left=(new Date(m.start_at).getTime()-start)/(end-start)*100,w=(new Date(m.due_at).getTime()-new Date(m.start_at).getTime())/(end-start)*100;return <div className="gantt-row" key={m.id}><div className="gantt-label"><Link href={'/tasks/'+m.id}><span className="module-id">{m.id}</span><strong>{m.title}</strong><small>{m.owner_name} · {fmt(m.due_at)}截止{overdue(m)?' · 逾期':''}</small></Link>{admin&&<button className="icon-button" onClick={()=>setEdit(m)} aria-label={`编辑${m.id}计划`}><Settings size={14}/></button>}</div><div className="gantt-track" style={{backgroundSize:`${100/columns}% 100%`}}>{today>=0&&today<=100&&<div className="today-line" style={{left:today+'%'}}/>}<Link title={`${m.id} ${m.title}：${fmt(m.start_at)} 至 ${fmt(m.due_at)}，${m.progress}%`} className={`gantt-bar ${m.status.toLowerCase()}`} style={{left:left+'%',width:Math.max(w,1)+'%'}} href={'/tasks/'+m.id}><i style={{width:m.progress+'%'}}/><span>{m.id} · {STATUS[m.status]} · {m.progress}%</span></Link></div></div>;})}</div></div></section><div className="section-heading timeline-title"><h2>关键里程碑</h2><span className="muted">默认计划可由组长调整</span></div><div className="milestone-grid">{data.milestones.map((m,i)=><section className={`panel milestone-card ${new Date(m.at).getTime()<Date.now()?'elapsed':''}`} key={m.id}><div className="milestone-number">{String(i+1).padStart(2,'0')}</div><div><div className="section-heading"><h3>{m.title}</h3>{admin&&<button className="icon-button" onClick={()=>setMilestone(m)} aria-label={'编辑里程碑'+m.title}><Settings size={15}/></button>}</div><strong className="milestone-date">{fmt(m.at)}</strong><p>{m.description}</p></div></section>)}</div>{edit&&<Modal title={`编辑 ${edit.id} 计划与要求`} close={()=>setEdit(null)}><EditTask m={edit} close={()=>setEdit(null)}/></Modal>}{milestone&&<Modal title="编辑里程碑" close={()=>setMilestone(null)}><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(await act('milestones/'+milestone.id,{title:f.get('title'),at:fromLocal(String(f.get('at'))),description:f.get('description')},'PATCH'))setMilestone(null);}}><Field label="名称"><input name="title" defaultValue={milestone.title} required/></Field><Field label="时间（北京时间）"><input type="datetime-local" name="at" defaultValue={localDate(milestone.at)} required/></Field><Field label="说明"><textarea name="description" rows={3} defaultValue={milestone.description}/></Field><Submit>保存里程碑</Submit></form></Modal>}</>;
}
function Resources(){const {data,act}=useApp(),admin=data.user.role==='ADMIN',[upload,setUpload]=useState(false),[category,setCategory]=useState(''),[editing,setEditing]=useState<Item|null>(null);const resources=data.resources.filter(r=>!category||r.category===category);return <><Heading eyebrow="COURSE LIBRARY" title="让每一条论据有据可查" detail="教师课件、教材资料与政策原文，集中保存并关联到研究模块。">{admin&&<button className="button primary" onClick={()=>setUpload(true)}><Plus size={17}/> 上传课程资料</button>}</Heading><div className="tabs">{['','教师PPT','课程作业要求','教材资料','官方政策文件','其他参考资料'].map(c=><button key={c} onClick={()=>setCategory(c)} className={c===category?'active':''}>{c||'全部资料'}</button>)}</div><div className="resource-grid">{resources.map(r=><section className="panel resource-card" key={r.id}><div className="section-heading"><span className="resource-icon"><FileText size={24}/></span><span className="section-tag">{r.category}</span></div><h3>{r.title}</h3><p>{r.description||'暂无简介'}</p><div className="resource-tags">{r.modules.length?r.modules.map((m:string)=><Link key={m} href={'/tasks/'+m} className="module-id">{m}</Link>):<span className="module-id">全部模块</span>}{!r.visible&&<span className="badge revision">仅组长可见</span>}</div><FileLinks files={r.files}/><div className="resource-bottom"><small>{fmt(r.created_at)}上传</small>{admin&&<button className="text-button" onClick={()=>setEditing(r)}>授权与关联</button>}</div></section>)}</div>{!resources.length&&<Empty title="此分类暂无资料" detail="组长可上传教师PPT、课程PDF或官方政策文件。"/>}{upload&&<Modal title="上传课程资料" close={()=>setUpload(false)}><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);f.set('modules',JSON.stringify(f.getAll('module')));f.set('visible',String(f.get('visible')==='on'));if(await act('resources',f))setUpload(false);}}><Field label="资料名称"><input name="title" required minLength={2}/></Field><Field label="分类"><select name="category">{['教师PPT','课程作业要求','教材资料','官方政策文件','其他参考资料'].map(c=><option key={c}>{c}</option>)}</select></Field><Field label="资料简介"><textarea name="description" rows={3}/></Field><FileInput required/><ModuleChecks/><label className="checkbox-line"><input name="visible" type="checkbox" defaultChecked/> 允许成员查看和下载</label><div className="form-footer"><Submit>上传并保存</Submit></div></form></Modal>}{editing&&<Modal title="资料授权与模块关联" close={()=>setEditing(null)}><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(await act('resources/'+editing.id,{visible:f.get('visible')==='on',modules:f.getAll('module')},'PATCH'))setEditing(null);}}><ModuleChecks selected={editing.modules}/><label className="checkbox-line"><input type="checkbox" name="visible" defaultChecked={!!editing.visible}/> 允许所有成员查看和下载（模块关联仅作检索分类）</label><div className="form-footer"><Submit>保存授权</Submit></div></form></Modal>}</>;}
function ModuleChecks({selected=[]}:{selected?:string[]}){const {data}=useApp();return <fieldset><legend>适用模块（不选表示全部）</legend><div className="module-checks">{data.modules.map(m=><label key={m.id}><input type="checkbox" name="module" value={m.id} defaultChecked={selected.includes(m.id)}/>{m.id} · {m.owner_name}</label>)}</div></fieldset>;}
function Members(){const {data,act}=useApp(),admin=data.user.role==='ADMIN',[adding,setAdding]=useState<Item|null>(null);return <><Heading eyebrow="PEOPLE & CONTRIBUTIONS" title="12位成员，共同完成一次好研究" detail="贡献归属于实际提交者，综合记录按时提交、修改回应、审核结果与额外协作。"/><div className="member-grid">{data.users.map(u=>{const m=data.modules.find(m=>m.owner_id===u.id),notes=data.contributions.filter(c=>c.user_id===u.id),stats=u.stats;return <section className={`panel member-card ${u.role==='ADMIN'?'leader-card':''}`} key={u.id}><div className="member-head"><Avatar name={u.name} admin={u.role==='ADMIN'}/><div><h3>{u.name}</h3><small>{u.id}</small></div><span className="section-tag">{u.role==='ADMIN'?'组长':'研究成员'}</span></div>{m?<Link className="member-task" href={'/tasks/'+m.id}><span className="module-id">{m.id}</span>{m.title}<ArrowUpRight size={15}/></Link>:<div className="member-task"><ShieldCheck size={17}/>{u.role==='ADMIN'?'项目统筹 · 审核 · PPT整合 · 课堂汇报':'项目进度未公开'}</div>}{m&&<Badge status={m.status}/>}<div className="member-stats">{stats?<><span><strong>{stats.submissions}</strong>提交次数</span><span><strong>{stats.on_time}</strong>按时提交</span><span><strong>{stats.approved}</strong>通过版本</span><span><strong>{stats.hours}</strong>提交工时</span></>:<p className="muted">贡献数据需组长授权后展示。</p>}</div>{stats&&<small className="muted">要求自查 {stats.requirements_met} 次 · 回应反馈 {stats.feedback_addressed} 次（成员自报）</small>}{notes.map(c=><div className="contribution-note" key={c.id}><p>{c.note}</p><small>{c.hours} 小时 · {fmt(c.created_at)} · {c.visible?'可供互评参考':'本人及组长可见'}</small></div>)}{admin&&<button className="text-button" onClick={()=>setAdding(u)}><Plus size={14}/> 添加贡献记录</button>}</section>;})}</div><div className="course-rule"><GraduationCap size={20}/><p>{COURSE_RULE}</p></div>{adding&&<Modal title={`记录 ${adding.name} 的贡献`} close={()=>setAdding(null)}><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(await act('contributions',{userId:adding.id,note:f.get('note'),hours:Number(f.get('hours')),visible:f.get('visible')==='on'}))setAdding(null);}}><Field label="具体贡献与依据"><textarea name="note" rows={5} minLength={2} required placeholder="例如统筹协调、协助核验来源、完善案例、审核材料、模拟答辩…"/></Field><Field label="额外协作工时（与提交工时分开记录）"><input type="number" name="hours" min="0" max="500" step="0.5" defaultValue="0"/></Field><label className="checkbox-line"><input type="checkbox" name="visible"/> 在组长开启贡献信息共享后，允许其他成员查看</label><div className="form-footer"><Submit>保存贡献记录</Submit></div></form></Modal>}</>;}
function PeerReview(){const {data,act}=useApp(),admin=data.user.role==='ADMIN';return <><Heading eyebrow="PEER FEEDBACK" title="让协作被看见" detail="结合公开成果与真实协作经历，给出简短、公平的评价。每人对每位同伴仅提交一次。">{admin&&<a className="button secondary" href="/api/exports/peers"><Download size={16}/> 导出Excel汇总</a>}</Heading><div className={`notice ${data.settings.peer_open?'success':'warning'}`}>{data.settings.peer_open?'组内互评已开启。提交后的评分与文字由组长汇总。':'组内互评尚未开启或已关闭，请等待组长安排。'}{admin&&<button className="text-button" onClick={()=>void act('settings',{peer_open:!data.settings.peer_open},'PATCH')}>{data.settings.peer_open?'关闭互评':'开启互评'}</button>}</div><div className="detail-grid"><section className="panel padded"><h2>评价一位同伴</h2><p className="muted">不能评价自己。请在“成员与贡献”及模块摘要中查看组长授权的资料。</p>{data.settings.peer_open?<form onSubmit={async e=>{e.preventDefault();const el=e.currentTarget,f=new FormData(el);if(await act('peer-reviews',{targetId:f.get('targetId'),score:Number(f.get('score')),comment:f.get('comment')}))el.reset();}}><Field label="被评价成员"><select name="targetId" required defaultValue=""><option value="" disabled>选择成员</option>{data.users.filter(u=>u.id!==data.user.id&&!data.peerReviews.some(p=>p.author_id===data.user.id&&p.target_id===u.id)).map(u=><option key={u.id} value={u.id}>{u.name}{u.role==='ADMIN'?'（项目统筹）':''}</option>)}</select></Field><Field label="协作贡献评价（1—5）"><select name="score" defaultValue="" required><option value="" disabled>请选择</option>{[5,4,3,2,1].map(n=><option key={n} value={n}>{n}分</option>)}</select></Field><Field label="具体意见"><textarea name="comment" minLength={2} maxLength={3000} rows={5} required placeholder="描述具体贡献，以及可以进一步改善的地方…"/></Field><Submit>提交互评</Submit></form>:<Empty title="互评通道已关闭" detail="已提交的评价会被保留。"/>}</section><section className="panel padded"><h2>{admin?'互评汇总':'我已提交的评价'} <span className="count">{data.peerReviews.length}</span></h2>{data.peerReviews.length?data.peerReviews.map(p=><div className="peer-record" key={p.id}><strong>{data.users.find(u=>u.id===p.author_id)?.name} <ArrowRight size={13}/> {data.users.find(u=>u.id===p.target_id)?.name}<span>{p.score} / 5</span></strong><p>{p.comment}</p><small>{fmt(p.created_at)}</small></div>):<p className="muted">尚无已提交评价。</p>}</section></div><p className="footnote">互评用于记录协作表现，不会自动换算为正式课程成绩。</p></>;}
function ExportPage(){const {data,download,busy}=useApp();const ready=data.modules.filter(completed).length;return <><Heading eyebrow="FINAL DELIVERY" title="把共同成果，整理成一份资料包" detail="导出每个模块最后审核通过的原始材料，用于后续ChatGPT与Canva汇报制作。"/><div className="export-grid"><section className="panel export-main"><span className="export-icon"><Download size={30}/></span><h2>最终研究资料包</h2><p>11个模块全部审核通过后，一键冻结批准版本并生成ZIP。</p><div className="export-readiness"><strong>{ready}<small> / 11</small></strong><span>个模块已通过或冻结</span></div><div className="progress-track"><span style={{width:ready/11*100+'%'}}/></div><button className="button primary export-button" disabled={ready!==11||busy} onClick={()=>{if(confirm('将冻结所有已通过的最新版本并导出最终资料包，之后如需修改可由组长重新开放。'))void download('final');}}><LockKeyhole size={17}/>{busy?'正在生成资料包…':'冻结并导出全部已审核材料'}</button>{ready!==11&&<small className="muted">尚有 {11-ready} 个模块未完成审核，请先前往审核中心处理。</small>}<div className="export-secondary"><button className="button secondary" disabled={busy||!data.submissions.length} onClick={()=>void download('all')}><Download size={16}/> 下载现有全部版本（工作包）</button><a className="text-link" href="/api/exports/brief">下载最终汇报提示词 <ArrowUpRight size={15}/></a></div></section><section className="panel padded"><h2>资料包内容</h2><div className="file-tree"><strong>MedPolicyLab_Final/</strong>{data.modules.map(m=><div key={m.id}><FolderOpen size={15}/><span>{m.id}_{data.submissions.filter(s=>s.module_id===m.id).sort((a,b)=>b.version-a.version)[0]?.submitter_name||m.owner_name}/</span>{completed(m)?<CheckCircle2 size={15} className="text-teal"/>:<Clock size={15} className="muted"/>}</div>)}<div><Library size={15}/> References/</div><div><FileText size={15}/> Presentation_Brief.md</div><div><FileText size={15}/> Submission_Manifest.csv</div></div><p className="footnote">成员目录以最终版本的原始提交人为准。清单包含版本、审核状态、摘要、来源索引与文件校验值。</p></section></div><section className="panel padded"><h2>最终汇报的下一步</h2><div className="export-steps"><div><span>01</span><h3>上传到ChatGPT</h3><p>提供ZIP与课程要求，整合11份审核材料的论点与证据。</p></div><div><span>02</span><h3>组织15分钟叙事</h3><p>教材 → 现实 → 必答思考，制作12—15页PPT与逐页中文讲稿。</p></div><div><span>03</span><h3>在Canva完成呈现</h3><p>完善图表、美化、课堂互动与演讲者备注，导出最终PPTX。</p></div></div></section></>;}
function Admin(){const {data,act}=useApp(),[reset,setReset]=useState<Item|null>(null);return <><Heading eyebrow="PROJECT ADMINISTRATION" title="组长管理中心" detail="管理账号、项目授权与操作记录。组长专注统筹，不承担R01—R11研究专题。"/><section className="panel padded"><h2>项目开关</h2><div className="settings-grid">{[['force_password_change','首次登录必须修改密码','正式多人使用前建议开启；成员修改后才能访问项目。'],['public_progress','公开项目整体进度','允许成员查看全部任务的进度与组长发布的成果摘要。'],['peer_open','开启组内互评','成员可评价其他成员，结果仅由组长汇总。'],['peer_summaries','共享贡献信息供互评参考','公开提交统计和组长标记可公开的贡献备注。']].map(([key,label,detail])=><label className="setting-row" key={key}><div><strong>{label}</strong><p>{detail}</p></div><input type="checkbox" role="switch" checked={!!data.settings[key]} onChange={e=>void act('settings',{[key]:e.target.checked},'PATCH')}/></label>)}</div></section><section className="panel"><div className="panel-heading"><h2>12个独立账号</h2><span className="muted">登录名使用完整学号</span></div><div className="table-wrap"><table><thead><tr><th>成员</th><th>学号 / 登录名</th><th>角色</th><th>密码状态</th><th>账号管理</th></tr></thead><tbody>{data.users.map(u=><tr key={u.id}><td><span className="person"><Avatar name={u.name}/>{u.name}</span></td><td className="mono">{u.id}</td><td>{u.role==='ADMIN'?'唯一管理员':'普通成员'}</td><td><span className={u.must_change?'text-amber':'text-teal'}>{u.must_change?'尚未修改初始/重置密码':'已设置个人密码'}</span></td><td>{u.role==='MEMBER'?<div className="actions-row"><button className="text-button" onClick={()=>setReset(u)}>重置密码</button><button className="text-button" onClick={()=>{if(confirm(`${u.disabled?'启用':'停用'} ${u.name} 的账号？现有会话会失效。`))void act('members/'+u.id,{disabled:!u.disabled},'PATCH');}}>{u.disabled?'启用账号':'停用账号'}</button></div>:<Link className="text-link" href="/account">修改我的密码</Link>}</td></tr>)}</tbody></table></div></section><section className="panel"><div className="panel-heading"><div><h2>操作记录</h2><p>展示最近100条；完整记录可导出。</p></div><a className="button secondary" href="/api/exports/logs"><Download size={15}/> 导出操作日志</a></div><div className="table-wrap audit-table"><table><thead><tr><th>时间</th><th>执行人</th><th>操作</th><th>对象与详情</th></tr></thead><tbody>{data.audit.map(a=><tr key={a.id}><td>{fmt(a.created_at)}</td><td>{a.actor_name||'系统'}</td><td className="mono">{a.action}</td><td><details><summary>{a.entity}</summary><pre>{JSON.stringify(JSON.parse(a.details),null,2)}</pre></details></td></tr>)}</tbody></table></div></section>{reset&&<Modal title={`重置 ${reset.name} 的密码`} close={()=>setReset(null)}><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(await act('members/'+reset.id,{password:f.get('password')},'PATCH'))setReset(null);}}><div className="soft-note">设置独立临时密码并私下告知成员。原会话会全部失效，成员再次登录后会收到改密提醒。</div><Field label="新临时密码（至少10位）"><input type="password" name="password" minLength={10} maxLength={128} autoComplete="new-password" required/></Field><Submit>重置并撤销旧会话</Submit></form></Modal>}</>;}
function PasswordForm({standalone=false,onDone}:{standalone?:boolean;onDone?:()=>void}){const [busy,setBusy]=useState(false),[message,setMessage]=useState('');return <form onSubmit={async e=>{e.preventDefault();setBusy(true);setMessage('');const el=e.currentTarget,f=new FormData(el);try{if(f.get('password')!==f.get('confirm'))throw new Error('两次新密码不一致');const r=await fetch('/api/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({current:f.get('current'),password:f.get('password')})});const j=await r.json();if(!r.ok)throw new Error(j.error);setMessage('密码已更新，其他旧会话已失效。');el.reset();onDone?.();if(standalone)location.assign('/my-task');}catch(e){setMessage((e as Error).message);}finally{setBusy(false);}}}><Field label="当前密码"><input type="password" name="current" autoComplete="current-password" required/></Field><Field label="新密码（至少10位）"><input type="password" name="password" autoComplete="new-password" minLength={10} maxLength={128} required/></Field><Field label="再次输入新密码"><input type="password" name="confirm" autoComplete="new-password" minLength={10} required/></Field>{message&&<div className="notice" role="status">{message}</div>}<button className="button primary" disabled={busy}><LockKeyhole size={16}/>{busy?'正在保存…':'修改密码'}</button></form>;}
function Account(){const {data,reload}=useApp();return <><Heading eyebrow="ACCOUNT SECURITY" title="账号与安全" detail={`${data.user.name} · ${data.user.id} · ${data.user.role==='ADMIN'?'项目管理员':'研究成员'}`}/><section className="panel padded account-panel"><h2>设置个人密码</h2><p className="muted">使用至少10位、不与其他网站共用的密码。修改后其他登录会话将失效。</p><PasswordForm onDone={()=>void reload()}/></section></>;}
